dashboard.definition:
{
    "title": "Schnittstellen und eHealth",
    "description": "Kommunikationsserver-Kanaele mit Durchsatz, Warteschlange und Latenz sowie die Gesundheit der oesterreichischen eHealth-Dienste",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Zeitraum",
            "options": {
                "token": "global_time",
                "defaultValue": "-4h@m,now"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        },
        "tokens": {
            "default": {
                "channel": {
                    "value": "*"
                }
            }
        }
    },
    "dataSources": {
        "ds_hl7": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as v WHERE index=demo_sakh_metrics metric_name IN (\"sakh.hl7.messages_in\", \"sakh.hl7.queue_depth\", \"sakh.hl7.avg_latency_ms\", \"sakh.hl7.ack_errors\") BY metric_name channel source_system target_system span=5m",
                "enableSmartSources": true
            },
            "name": "HL7-Metriken (5 min)"
        },
        "ds_flow": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:hl7:engine\" earliest=-5m\n| stats sum(messages_in) as messages latest(queue_depth) as queue_depth latest(avg_latency_ms) as avg_latency_ms latest(status) as status latest(message_type) as message_type by channel source_system target_system",
                "enableSmartSources": true
            },
            "name": "Kanaele jetzt"
        },
        "ds_k_msgs": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_hl7",
                "query": "| where metric_name=\"sakh.hl7.messages_in\" | timechart span=5m sum(v) as \"Nachrichten/min\""
            }
        },
        "ds_k_queue": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_hl7",
                "query": "| where metric_name=\"sakh.hl7.queue_depth\" | timechart span=5m sum(v) as Warteschlange"
            }
        },
        "ds_k_ack": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_hl7",
                "query": "| where metric_name=\"sakh.hl7.ack_errors\" | timechart span=5m sum(v) as \"ACK-Fehler\""
            }
        },
        "ds_k_stopped": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_flow",
                "query": "| where status=\"gestoppt\" OR status=\"Stau\" | stats count as \"Gestoerte Kanaele\""
            }
        },
        "ds_k_elga": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as v WHERE index=demo_sakh_metrics metric_name=\"sakh.ehealth.error_pct\" span=15m | rename v as \"eHealth Fehler %\"",
                "enableSmartSources": true
            }
        },
        "ds_k_ecs": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as v WHERE index=demo_sakh_metrics metric_name=\"sakh.ehealth.avg_response_ms\" service=\"ecard_ecs\" span=15m | rename v as \"e-card ms\"",
                "enableSmartSources": true
            }
        },
        "ds_queue": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_hl7",
                "query": "| where metric_name=\"sakh.hl7.queue_depth\" AND channel=\"$channel$\" | timechart span=5m limit=0 max(v) by channel"
            }
        },
        "ds_latency": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_hl7",
                "query": "| where metric_name=\"sakh.hl7.avg_latency_ms\" AND channel=\"$channel$\" | timechart span=5m limit=0 avg(v) by channel"
            }
        },
        "ds_heat": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_hl7",
                "query": "| where metric_name=\"sakh.hl7.queue_depth\" | timechart span=5m limit=0 max(v) by channel"
            }
        },
        "ds_table": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_flow",
                "query": "| eval Status=status\n| table channel source_system target_system message_type messages queue_depth avg_latency_ms Status\n| rename channel as Kanal source_system as Quelle target_system as Ziel message_type as Nachricht messages as \"Nachrichten (5 min)\" queue_depth as Warteschlange avg_latency_ms as \"Latenz ms\""
            }
        },
        "ds_eh": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:ehealth\" type=service earliest=-15m\n| stats latest(service_name) as Dienst latest(requests) as \"Anfragen (5 min)\" latest(error_pct) as \"Fehler %\" latest(avg_response_ms) as \"Antwort ms\" latest(status) as Status by service | fields - service",
                "enableSmartSources": true
            }
        },
        "ds_eh_rt": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as v WHERE index=demo_sakh_metrics metric_name=\"sakh.ehealth.avg_response_ms\" BY service_name span=15m | timechart span=15m avg(v) by service_name",
                "enableSmartSources": true
            }
        },
        "ds_docs": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:ehealth\" type=document | timechart span=30m count by status",
                "enableSmartSources": true
            }
        },
        "ds_doc_type": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:ehealth\" type=document | chart count over document_type by status",
                "enableSmartSources": true
            }
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_studio/images/nav_home.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_studio",
                        "dashboard": "kis_home",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_care": {
