        "viz_01": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_msgs"
            },
            "options": {
                "majorColor": "#2dd4bf",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            }
        },
        "viz_02": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_queue"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 50,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 50,
                        "to": 200,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 200,
                        "value": "#ff4d6d"
                    }
                ]
            }
        },
        "viz_03": {
